  it('returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round', async () => {
    const registry = new ToolRegistry();
    let executeCalledWith: Record<string, unknown> | null = null;
    const execute: ToolExecutor = async input => {
      executeCalledWith = input;
      return 'ok';
    };
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      execute
    );

    const call1: MessageChunk = {
      type: 'tool_use',
      toolCall: {id: 'c1', name: 'weather', input: {}},
    };
    const call2: MessageChunk = {
      type: 'tool_use',
      toolCall: {id: 'c2', name: 'weather', input: {location: 'London'}},
    };

    const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
    const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};

    const capturedMessages: SendMessageParams[] = [];
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        capturedMessages.push(params);
        if (capturedMessages.length === 1) {
          yield call1;
          yield STOP_FOR_TOOL;
        } else if (capturedMessages.length === 2) {
          yield call2;
          yield STOP_FOR_TOOL;
        } else {
          yield {type: 'text', text: 'done'};
          yield STOP_DONE;
        }
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    await orchestrator.processMessage(createSession('start'));

    expect({
      roundCount: capturedMessages.length,
      round2LastMessage: capturedMessages[1].messages[capturedMessages[1].messages.length - 1],
      executeCalledWith,
    }).toMatchObject({
      roundCount: 3,
      round2LastMessage: {
        role: 'user',
        content: [
          {
            type: 'tool_result',
            toolUseId: 'c1',
            content: expect.stringMatching(/required.*location/i),
          },
        ],
      },
      executeCalledWith: {location: 'London'},
    });
  });
});

